"""Inspect SQLite database(s) in this workspace to learn their schema.

Task-local helper: only reads local database metadata so the login script
can be written against the actual schema. No writes are performed.
"""

import sqlite3
import sys
from pathlib import Path

CANDIDATE_SUFFIXES = (".db", ".sqlite", ".sqlite3", ".db3")


def find_databases() -> list[Path]:
    """Return SQLite database files found in the workspace (no duplicates)."""
    candidates: list[Path] = []
    for base in (Path.cwd(), Path(__file__).resolve().parent):
        for path in sorted(base.iterdir()):
            if path.is_file() and path.suffix.lower() in CANDIDATE_SUFFIXES:
                if path not in candidates:
                    candidates.append(path)
    return candidates


def describe_database(path: Path) -> None:
    """Print the user tables and their columns for one database file."""
    print(f"=== {path} ===")
    with sqlite3.connect(path) as conn:
        tables = [
            row[0]
            for row in conn.execute(
                "SELECT name FROM sqlite_master "
                "WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
            )
        ]
        if not tables:
            print("  (no user tables)")
        for table in tables:
            print(f"  table: {table}")
            for _cid, name, ctype, notnull, dflt, pk in conn.execute(
                f'PRAGMA table_info("{table}")'
            ):
                print(
                    f"    column: {name} | type: {ctype} | notnull: {notnull} "
                    f"| default: {dflt!r} | pk: {pk}"
                )


def main() -> int:
    dbs = find_databases()
    if not dbs:
        print("No SQLite database files found in this folder.")
        return 1
    for db in dbs:
        describe_database(db)
    return 0


if __name__ == "__main__":
    sys.exit(main())

